<?php include 'conexao.php';if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']??'');$desc=trim($_POST['descricao']??'');if($nome!==''){$stmt=$conn->prepare('INSERT INTO produtos(nome,descricao) VALUES(?,?)');$stmt->bind_param('ss',$nome,$desc);$stmt->execute();header('Location:index.php');exit;}}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Novo produto • CRUD</title><link rel="stylesheet" href="style.css"></head><body><header class="navbar"><div class="container nav-inner"><a class="brand" href="index.php">CRUD<span>Produtos</span></a><div class="nav-badge">Novo cadastro</div></div></header><main class="main"><div class="container"><div class="form-card card"><div class="eyebrow">Cadastro</div><h1 class="title">Novo produto</h1><p class="subtitle" style="margin-bottom:28px">Preencha os dados abaixo para adicionar um produto.</p><form method="post"><div class="form-group"><label class="label">Nome do produto</label><input class="input" name="nome" required maxlength="100" placeholder="Ex.: Teclado mecânico"></div><div class="form-group"><label class="label">Descrição</label><textarea class="textarea" name="descricao" placeholder="Digite uma descrição para o produto..."></textarea></div><div class="form-actions"><a class="btn btn-secondary" href="index.php">Cancelar</a><button class="btn btn-primary" type="submit">＋ Cadastrar produto</button></div></form></div></div></main></body></html>